// AI layer (REVIEW_ISSUES R06): checks AI-written text against the computed data and publishes it.
// Run after build_data.mjs:   node pipeline/ai_build.mjs [--context]
//
// Inputs, written with Claude Code (or regenerated by pipeline/ai/generate.mjs) from pipeline/ai/context.md:
//   pipeline/ai/briefs.json   one interpretation brief per environment preset x task   (R06b)
//   pipeline/ai/qa.json       curated "Ask the evidence" questions and answers           (R06c)
//   pipeline/ai/related.json  related investigations with a one-line reason             (R06e)
// Every sentence carries `cites`. The build fails (R06d) unless, for every sentence:
//   - it has at least one cite, and every cite resolves: PSI-n (investigation), F<n> (checked finding,
//     app/public/data/findings.json), gap:<id> or gap:<env>/<id> (computed gap), env or env:<id>
//     (environment values), stat:<key> (computed insight);
//   - every number in it appears in the text or data of what it cites (ranking scores included);
//   - every investigation it names by acronym is among its cites;
//   - "closest" points cite only investigations in the top 5 of the computed ranking for that view.
// --context writes pipeline/ai/context.json and context.md: the computed rankings, gaps and findings
// for every view, which is all the AI is given to write from.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { explain, rank } from '../app/src/lib/ranker.ts'

const HERE = dirname(fileURLToPath(import.meta.url))
const DATA = join(HERE, '..', 'app', 'public', 'data')
const AI = join(HERE, 'ai')
const load = (dir, f) => JSON.parse(readFileSync(join(dir, f), 'utf8'))
const INV = load(DATA, 'investigations.json'), ENV = load(DATA, 'environments.json'), GAPS = load(DATA, 'gaps.json')
const FINDINGS = load(DATA, 'findings.json'), INSIGHTS = load(DATA, 'insights.json'), SOURCES = load(DATA, 'sources.json')
const RAW = (id) => load(join(HERE, 'raw'), `${id}.json`)
const byId = Object.fromEntries(INV.map((i) => [i.psi_id, i]))
const modeling = Object.fromEntries(SOURCES.psi.filter((s) => s.used_as !== 'ranked investigation').map((s) => [s.psi_id, s]))
const findingById = Object.fromEntries(FINDINGS.map((f) => [f.id, f]))
const envById = Object.fromEntries(ENV.environments.map((e) => [e.id, e]))
const gapsByEnv = Object.fromEntries(GAPS.map((g) => [g.environment_id, g.gaps]))
const W = ENV.default_weights, SPANS = ENV.reference_spans
const TOP = 5

// ---------- computed views: ranking for every preset x task ----------
const views = {}
for (const e of ENV.environments) for (const t of ENV.tasks) {
  const ranked = rank(e, t, W, INV, SPANS)
  views[`${e.id}/${t.id}`] = { env: e, task: t, ranked, top: ranked.slice(0, TOP).map((r) => r.inv.psi_id) }
}

// ---------- what each cite contributes as checkable text ----------
const n1 = (x) => (x === null || x === undefined ? '' : `${x} ${Math.round(x * 10) / 10} ${Math.round(x)}`)
const condText = (c) => (c ? `${n1(c.min)} ${n1(c.max)}` : '')
const invText = (i, viewKeys) => {
  let s = `${i.acronym} ${i.title} O2 ${condText(i.conditions.o2_percent)} pressure ${condText(i.conditions.pressure_kpa)} flow ${condText(i.conditions.flow_cm_s)} runs ${i.evidence.n_runs} publications ${i.n_publications} ${i.start_date} ${i.end_date} ${i.fuel_materials.join(' ')} ${i.geometry ?? ''} ${i.hardware ?? ''}`
  for (const k of viewKeys) {
    const item = views[k].ranked.find((x) => x.inv.psi_id === i.psi_id)
    s += ` relevance ${item.relevance} factors ${item.n_known} of ${item.n_scored} ${item.flags.join(' ')} ${explain(item).join(' ')}`
  }
  return s
}
const envText = (e) => `${e.name} ${e.o2_percent} % O2 ${e.pressure_kpa} kPa ${e.gravity_g} g ${e.note ?? ''} ${e.sources.map((s) => s.note ?? '').join(' ')}`
// Digits inside formulas (O2, CO2, SF6, C2H4) are not quantities.
const numbersIn = (s) => [...String(s).matchAll(/(?<![A-Za-z\d.])\d+(?:\.\d+)?/g)].map((m) => m[0].replace(/\.0+$/, ''))

// Names a sentence can use for an investigation (acronym, without the ACME prefix, each half of "A / B").
const ALIASES = INV.flatMap((i) => {
  const names = new Set([i.acronym, i.acronym.replace(/^ACME /, ''), ...i.acronym.split(' / ')])
  for (const n of [...names]) if (/^SAFFIRE/.test(n)) names.add(n.replace('SAFFIRE', 'Saffire'))
  return [...names].filter((n) => n.length >= 3).map((n) => ({ id: i.psi_id, re: new RegExp(`(?<![\\w-])${n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\w-])`) }))
})

/** Checks one sentence; returns error strings. envIds: environments the text is shown for. */
function checkSentence(where, s, { envIds = [], viewKeys = [], closest = false } = {}) {
  const errs = []
  if (!s.text || !Array.isArray(s.cites) || s.cites.length === 0) return [`${where}: needs text and at least one cite`]
  let corpus = ''
  const citedPsi = new Set()
  for (const c of s.cites) {
    if (/^PSI-\d+$/.test(c)) {
      if (byId[c]) { corpus += ' ' + invText(byId[c], viewKeys); citedPsi.add(c) } else if (modeling[c]) { corpus += ' ' + modeling[c].title; citedPsi.add(c) } else errs.push(`${where}: unknown investigation ${c}`)
    } else if (/^F\d+$/.test(c)) {
      const f = findingById[c]
      if (!f) { errs.push(`${where}: unknown finding ${c}`); continue }
      corpus += ` ${f.text} ${f.quote ?? ''} ${f.cells.map((x) => `${x.column} ${x.value}`).join(' ')}`
    } else if (c.startsWith('gap:')) {
      const [envId, gapId] = c.slice(4).includes('/') ? c.slice(4).split('/') : [null, c.slice(4)]
      const envs = envId ? [envId] : envIds
      if (!envs.length) { errs.push(`${where}: ${c} needs an environment (gap:<env>/<id>)`); continue }
      for (const e of envs) {
        const g = (gapsByEnv[e] ?? []).find((x) => x.id === gapId)
        if (!g) errs.push(`${where}: environment ${e} has no computed gap ${gapId}`)
        else corpus += ` ${g.text} ${g.computed_from.value}`
      }
    } else if (c === 'env' || c.startsWith('env:')) {
      const envs = c === 'env' ? envIds : [c.slice(4)]
      for (const e of envs) envById[e] ? (corpus += ' ' + envText(envById[e])) : errs.push(`${where}: unknown environment ${e}`)
    } else if (c.startsWith('stat:')) {
      const v = INSIGHTS[c.slice(5)]
      if (v === undefined) errs.push(`${where}: unknown insight ${c}`)
      else corpus += ` ${c.slice(5).replace(/_/g, ' ')} ${JSON.stringify(v)}`
    } else errs.push(`${where}: cite ${c} is not a PSI ID, finding, gap, env or stat`)
  }
  // Rankings differ between the environments a shared brief covers, so a number must hold for all of them.
  const have = new Set(numbersIn(corpus))
  for (const n of numbersIn(s.text)) if (!have.has(n)) errs.push(`${where}: number ${n} is not in what it cites (${s.cites.join(', ')})`)
  for (const a of ALIASES) if (a.re.test(s.text) && !citedPsi.has(a.id)) errs.push(`${where}: names ${byId[a.id].acronym} but does not cite ${a.id}`)
  if (closest) for (const k of viewKeys) for (const id of citedPsi) if (!views[k].top.includes(id)) errs.push(`${where}: ${id} is not in the top ${TOP} for ${k} (top: ${views[k].top.join(', ')})`)
  return errs
}

// ---------- context for the writer ----------
if (process.argv.includes('--context')) {
  const ctx = { note: 'Everything the AI writer is given. Generated by node pipeline/ai_build.mjs --context; do not edit.', weights: W, views: {}, gaps: gapsByEnv, findings: FINDINGS.map(({ id, psi_ids, kind, text }) => ({ id, psi_ids, kind, text })), insights: INSIGHTS }
  let md = '# AI writer context (generated; do not edit)\n\nRankings use the default weights. Cite PSI IDs, findings (F<n>), gaps (gap:<id>), env, stat:<key>.\n'
  for (const [k, v] of Object.entries(views)) {
    ctx.views[k] = { env: v.env, task: v.task.id, top: v.ranked.slice(0, 8).map((r) => ({ psi_id: r.inv.psi_id, acronym: r.inv.acronym, relevance: r.relevance, recorded: `${r.n_known}/${r.n_scored}`, flags: r.flags, explain: explain(r), findings: r.inv.findings.map((f) => f.id) })) }
    md += `\n## ${k}: ${v.env.name} (${v.env.o2_percent}% O2, ${v.env.pressure_kpa} kPa, ${v.env.gravity_g} g) · ${v.task.name}\n`
    for (const r of ctx.views[k].top) md += `- ${r.psi_id} ${r.acronym}: ${r.relevance} (${r.recorded} recorded) · ${r.flags.join('; ') || 'no flags'} · findings ${r.findings.join(', ') || 'none'}\n`
  }
  md += '\n## Gaps\n'
  for (const [e, gs] of Object.entries(gapsByEnv)) for (const g of gs) md += `- gap:${e}/${g.id} (${g.severity}): ${g.text}\n`
  md += '\n## Findings\n'
  for (const f of FINDINGS) md += `- ${f.id} [${f.kind}] ${f.psi_ids.join(', ')}: ${f.text}\n`
  writeFileSync(join(AI, 'context.json'), JSON.stringify(ctx, null, 1) + '\n')
  writeFileSync(join(AI, 'context.md'), md)
  console.log('wrote pipeline/ai/context.json and context.md')
  process.exit(0)
}

const errors = []
const GEN = load(AI, 'meta.json')

// ---------- R06b briefs ----------
const BRIEF_KINDS = ['headline', 'closest', 'found', 'untested', 'next']
const briefsIn = load(AI, 'briefs.json').briefs
const covered = new Set()
const briefs = briefsIn.map((b, k) => {
  const where = `briefs.json #${k + 1} (${b.env_ids.join('+')}/${b.task_id})`
  if (!ENV.tasks.some((t) => t.id === b.task_id)) errors.push(`${where}: unknown task`)
  for (const e of b.env_ids) {
    if (!envById[e]) errors.push(`${where}: unknown environment ${e}`)
    if (covered.has(`${e}/${b.task_id}`)) errors.push(`${where}: second brief for ${e}/${b.task_id}`)
    covered.add(`${e}/${b.task_id}`)
  }
  const viewKeys = b.env_ids.map((e) => `${e}/${b.task_id}`).filter((v) => views[v])
  b.points.forEach((p, j) => {
    if (!BRIEF_KINDS.includes(p.kind)) errors.push(`${where} point ${j + 1}: kind must be one of ${BRIEF_KINDS.join(', ')}`)
    errors.push(...checkSentence(`${where} point ${j + 1}`, p, { envIds: b.env_ids, viewKeys, closest: p.kind === 'closest' }))
  })
  return { env_ids: b.env_ids, task_id: b.task_id, points: b.points.map(({ kind, text, cites }) => ({ kind, text, cites })) }
})
for (const k of Object.keys(views)) if (!covered.has(k)) errors.push(`briefs.json: no brief for ${k}`)

// ---------- R06c curated questions ----------
const qaIn = load(AI, 'qa.json').questions
const qa = qaIn.map((q, k) => {
  const where = `qa.json ${q.id ?? '#' + (k + 1)}`
  if (!q.id || !q.question || !Array.isArray(q.answer) || !q.answer.length) errors.push(`${where}: needs id, question and answer`)
  q.answer.forEach((s, j) => errors.push(...checkSentence(`${where} sentence ${j + 1}`, s)))
  return { id: q.id, question: q.question, tags: q.tags ?? [], answer: q.answer.map(({ text, cites }) => ({ text, cites })) }
})
if (new Set(qa.map((q) => q.id)).size !== qa.length) errors.push('qa.json: duplicate id')

// ---------- R06e related investigations ----------
// A reason may only claim a connection the data supports.
const family = (i) => {
  const h = `${i.hardware ?? ''} ${RAW(i.psi_id).experimentHardware ?? ''}`
  if (/ACME/i.test(h)) return 'ACME burners in the Combustion Integrated Rack'
  if (/Droplet/i.test(h)) return 'Multi-user Droplet Combustion Apparatus in the Combustion Integrated Rack'
  if (/Saffire|Cygnus/i.test(h)) return 'Saffire flow unit in a Cygnus cargo vehicle'
  if (/Soot Diagnostic|P-Trak/i.test(h)) return 'SAME smoke-measurement instruments'
  if (/Glovebox|MSG/i.test(h) || i.psi_id === 'PSI-106') return 'flow duct in the Microgravity Science Glovebox'
  return null
}
const psiLinked = (a, b) => [RAW(a).related_glds, RAW(b).related_glds].some((s, n) => (s ?? '').split(',').map((x) => x.trim()).includes(n ? a : b))
const BASIS = {
  psi_link: (a, b) => psiLinked(a, b),
  hardware: (a, b) => family(byId[a]) !== null && family(byId[a]) === family(byId[b]),
  fuel: (a, b) => byId[a].fuel_class === byId[b].fuel_class,
  role: (a, b) => byId[a].fire_safety_role === byId[b].fire_safety_role || byId[a].secondary_roles.includes(byId[b].fire_safety_role) || byId[b].secondary_roles.includes(byId[a].fire_safety_role),
  finding: (a, b) => FINDINGS.some((f) => f.psi_ids.includes(a) && f.psi_ids.includes(b)),
}
const relatedIn = load(AI, 'related.json').related
const related = {}
for (const [from, list] of Object.entries(relatedIn)) {
  if (!byId[from]) { errors.push(`related.json: unknown investigation ${from}`); continue }
  related[from] = list.map((r, j) => {
    const where = `related.json ${from} -> ${r.psi_id}`
    if (!byId[r.psi_id] || r.psi_id === from) errors.push(`${where}: bad target`)
    if (!r.basis?.length) errors.push(`${where}: needs a basis`)
    for (const b of r.basis ?? []) if (!BASIS[b]) errors.push(`${where}: unknown basis ${b}`); else if (byId[r.psi_id] && !BASIS[b](from, r.psi_id)) errors.push(`${where}: basis "${b}" is not supported by the data`)
    errors.push(...checkSentence(`${where} (${j + 1})`, { text: r.reason, cites: [from, r.psi_id, ...(r.cites ?? [])] }))
    return { psi_id: r.psi_id, reason: r.reason, basis: r.basis, hardware_family: r.basis?.includes('hardware') ? family(byId[from]) : null }
  })
}
// PSI's own links must all be offered (R37).
for (const i of INV) for (const j of INV) if (i !== j && psiLinked(i.psi_id, j.psi_id) && !(related[i.psi_id] ?? []).some((r) => r.psi_id === j.psi_id)) errors.push(`related.json: PSI links ${i.psi_id} and ${j.psi_id}, but ${i.psi_id} does not list it`)

if (errors.length) {
  console.error(`AI text check failed (${errors.length}):\n  ${errors.join('\n  ')}`)
  process.exit(1)
}
const label = { generated_with: GEN.generated_with, model: GEN.model, date: GEN.date, checked: 'Every number, cited ID and named investigation is checked against the computed data at build time (pipeline/ai_build.mjs).', human_reviewed: GEN.human_reviewed ?? false }
const w = (f, o) => writeFileSync(join(DATA, f), JSON.stringify(o, null, 1))
w('briefs.json', { ...label, briefs }); w('qa.json', { ...label, questions: qa }); w('related.json', { ...label, related })
console.log(`AI text OK: ${briefs.length} briefs covering ${covered.size} views, ${qa.length} questions, ${Object.values(related).flat().length} related links`)
